from .base_wrapper import BaseWrapper
from .airphone_wrapper import _AirphoneWrapper
from .cbts_wrapper import _CBTSWrapper
from .control_wrapper import _ControlWrapper
from .epcsim_wrapper import _EPCSimWrapper
from .host_wrapper import _HostWrapper
from .lteemu_wrapper import _LTEemuWrapper
from .rf_wrapper import _RFWrapper
from .tm500_wrapper import _TM500Wrapper


class TestlineWrapper(BaseWrapper):
    """
    Main wrapper class redirecting every field of old testline configuration
    to proper wrappers inside this library.
    """
    def __init__(self, tl_config):
        super(TestlineWrapper, self).__init__(tl_config)

        # Every attribute from OLD configuration
        # should be accessible from wrapper
        self._host = _HostWrapper(tl_config)
        self._cbts = _CBTSWrapper(tl_config)
        self._rf = _RFWrapper(tl_config)
        self._control = _ControlWrapper(tl_config)
        self._airphone = _AirphoneWrapper(tl_config)
        self._tm500 = _TM500Wrapper(tl_config)
        self._lteemu = _LTEemuWrapper(tl_config)
        self._epcsim = _EPCSimWrapper(tl_config)

        # Every attribute from NEW configuration
        # should be accessible from wrapper
        self.test_pc = tl_config.test_pc
        self.gnbs = tl_config.gnbs
        self.cloud_hostings = tl_config.cloud_hostings
        self.enbs = tl_config.enbs
        self.ues = tl_config.ues
        self.core = tl_config.core
        self.pdus = tl_config.pdus
        self.nms = tl_config.nms
        self.cbam = tl_config.cbam
        self.tl_cloud_topology = tl_config.tl_cloud_topology
        self.hardware_controllers = tl_config.hardware_controllers
        self.paragonx = tl_config.paragonx
        self.caffeine = tl_config.caffeine
        self.switches = tl_config.switches

    @property
    def host(self):
        return self._host

    @property
    def cbts(self):
        return self._cbts

    @property
    def rf(self):
        return self._rf

    @property
    def control(self):
        return self._control

    @property
    def airphone(self):
        return self._airphone

    @property
    def tm500(self):
        return self._tm500

    @property
    def lteemu(self):
        return self._lteemu

    @property
    def epcsim(self):
        return self._epcsim
